fn wizard_step_id() -> String {
    Uuid::new_v4().to_string()
}

fn wizard_value_to_string(value: &serde_json::Value) -> String {
    match value {
        serde_json::Value::Null => String::new(),
        serde_json::Value::String(s) => s.to_string(),
        serde_json::Value::Number(n) => n.to_string(),
        serde_json::Value::Bool(b) => b.to_string(),
        _ => String::new(),
    }
}

fn wizard_value_to_bool(value: &serde_json::Value) -> bool {
    match value {
        serde_json::Value::Bool(b) => *b,
        serde_json::Value::Number(n) => n.as_i64().unwrap_or(0) != 0,
        serde_json::Value::String(s) => {
            matches!(
                s.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "yes" | "y" | "on"
            )
        }
        _ => false,
    }
}

fn wizard_value_to_string_vec(value: &serde_json::Value) -> Vec<String> {
    match value {
        serde_json::Value::Array(items) => items
            .iter()
            .map(wizard_value_to_string)
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
            .collect(),
        serde_json::Value::String(s) => {
            let trimmed = s.trim();
            if trimmed.is_empty() {
                Vec::new()
            } else {
                vec![trimmed.to_string()]
            }
        }
        _ => Vec::new(),
    }
}

fn wizard_note_step(title: &str, message: &str) -> (String, serde_json::Value) {
    let id = wizard_step_id();
    let step = json!({
        "id": id,
        "type": "note",
        "title": title,
        "message": message,
        "executor": "client",
    });
    (
        step.get("id")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string(),
        step,
    )
}

fn wizard_confirm_step(message: &str, initial_value: bool) -> (String, serde_json::Value) {
    let id = wizard_step_id();
    let step = json!({
        "id": id,
        "type": "confirm",
        "message": message,
        "initialValue": initial_value,
        "executor": "client",
    });
    (
        step.get("id")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string(),
        step,
    )
}

fn wizard_text_step(
    message: &str,
    initial_value: Option<serde_json::Value>,
    placeholder: Option<&str>,
    sensitive: bool,
) -> (String, serde_json::Value) {
    let id = wizard_step_id();
    let mut step = json!({
        "id": id,
        "type": "text",
        "message": message,
        "executor": "client",
        "sensitive": sensitive,
    });
    if let Some(v) = initial_value {
        if let Some(obj) = step.as_object_mut() {
            obj.insert("initialValue".to_string(), v);
        }
    }
    if let Some(ph) = placeholder {
        if let Some(obj) = step.as_object_mut() {
            obj.insert("placeholder".to_string(), json!(ph));
        }
    }
    (
        step.get("id")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string(),
        step,
    )
}

