fn resolve_openclaw_cron_store_path(state: &GatewayState) -> PathBuf {
    resolve_openclaw_state_dir(state)
        .map(|dir| dir.join("cron").join("jobs.json"))
        .unwrap_or_else(|| PathBuf::from("cron").join("jobs.json"))
}

fn load_cron_store(store_path: &PathBuf) -> CronStoreFile {
    read_json_file::<CronStoreFile>(store_path).unwrap_or(CronStoreFile {
        version: 1,
        jobs: Vec::new(),
    })
}

fn resolve_cron_run_log_path(store_path: &PathBuf, job_id: &str) -> PathBuf {
    let dir = store_path
        .parent()
        .unwrap_or_else(|| std::path::Path::new("."));
    dir.join("runs").join(format!("{}.jsonl", job_id))
}

fn append_cron_run_log(entry_path: &PathBuf, entry: &serde_json::Value) -> std::io::Result<()> {
    use std::io::Write;

    const MAX_BYTES: u64 = 2_000_000;
    const KEEP_LINES: usize = 2_000;

    if let Some(parent) = entry_path.parent() {
        std::fs::create_dir_all(parent)?;
    }

    // Append JSONL line.
    let mut line = serde_json::to_string(entry).unwrap_or_else(|_| "{}".to_string());
    line.push('\n');
    std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(entry_path)?
        .write_all(line.as_bytes())?;

    // Prune if needed.
    let size = std::fs::metadata(entry_path).map(|m| m.len()).unwrap_or(0);
    if size <= MAX_BYTES {
        return Ok(());
    }

    let raw = std::fs::read_to_string(entry_path).unwrap_or_default();
    let mut lines: Vec<&str> = raw
        .split('\n')
        .map(|l| l.trim())
        .filter(|l| !l.is_empty())
        .collect();
    if lines.len() > KEEP_LINES {
        lines = lines.split_off(lines.len().saturating_sub(KEEP_LINES));
    }
    let tmp = entry_path.with_extension(format!(
        "{}.tmp",
        Uuid::new_v4().to_string().replace('-', "")
    ));
    std::fs::write(&tmp, format!("{}\n", lines.join("\n")))?;
    std::fs::rename(&tmp, entry_path)?;
    Ok(())
}

fn read_cron_run_log_entries(
    entry_path: &PathBuf,
    job_id: &str,
    limit: usize,
) -> Vec<serde_json::Value> {
    let limit = limit.clamp(1, 5000);
    let raw = std::fs::read_to_string(entry_path).unwrap_or_default();
    if raw.trim().is_empty() {
        return Vec::new();
    }

    let mut parsed: Vec<serde_json::Value> = Vec::new();
    let lines: Vec<&str> = raw.split('\n').collect();
    for i in (0..lines.len()).rev() {
        if parsed.len() >= limit {
            break;
        }
        let line = lines[i].trim();
        if line.is_empty() {
            continue;
        }
        let Ok(obj) = serde_json::from_str::<serde_json::Value>(line) else {
            continue;
        };
        let Some(o) = obj.as_object() else {
            continue;
        };
        if o.get("action").and_then(|v| v.as_str()) != Some("finished") {
            continue;
        }
        if o.get("jobId").and_then(|v| v.as_str()) != Some(job_id) {
            continue;
        }
        if o.get("ts").and_then(|v| v.as_u64()).is_none() {
            continue;
        }
        parsed.push(obj);
    }
    parsed.reverse();
    parsed
}

fn assert_supported_job_spec(job: &CronJob) -> Result<(), ErrorShape> {
    match job.session_target {
        CronSessionTarget::Main => match job.payload {
            CronPayload::SystemEvent { .. } => Ok(()),
            _ => Err(ErrorShape::new(
                error_codes::INVALID_REQUEST,
                r#"main cron jobs require payload.kind="systemEvent""#,
            )),
        },
        CronSessionTarget::Isolated => match job.payload {
            CronPayload::AgentTurn { .. } => Ok(()),
            _ => Err(ErrorShape::new(
                error_codes::INVALID_REQUEST,
                r#"isolated cron jobs require payload.kind="agentTurn""#,
            )),
        },
    }
}

fn assert_delivery_support(job: &CronJob) -> Result<(), ErrorShape> {
    if job.delivery.is_some() && !matches!(job.session_target, CronSessionTarget::Isolated) {
        return Err(ErrorShape::new(
            error_codes::INVALID_REQUEST,
            r#"cron delivery config is only supported for sessionTarget="isolated""#,
        ));
    }
    Ok(())
}

fn cron_normalize_channel(raw: Option<&str>) -> Option<String> {
    let raw = raw.unwrap_or("").trim();
    if raw.is_empty() {
        None
    } else {
        Some(raw.to_ascii_lowercase())
    }
}

fn cron_normalize_to(raw: Option<&str>) -> Option<String> {
    let raw = raw.unwrap_or("").trim();
    if raw.is_empty() {
        None
    } else {
        Some(raw.to_string())
    }
}

fn cron_has_legacy_delivery_hints(payload: &CronPayload) -> bool {
    let CronPayload::AgentTurn {
        deliver,
        to,
        best_effort_deliver,
        ..
    } = payload
    else {
        return false;
    };
    if deliver.is_some() {
        return true;
    }
    if best_effort_deliver.is_some() {
        return true;
    }
    if to.as_ref().map(|s| !s.trim().is_empty()).unwrap_or(false) {
        return true;
    }
    false
}

fn cron_delivery_from_legacy_payload(payload: &CronPayload) -> Option<CronDelivery> {
    let CronPayload::AgentTurn {
        deliver,
        channel,
        to,
        best_effort_deliver,
        ..
    } = payload
    else {
        return None;
    };
    let mode = if deliver == &Some(false) {
        CronDeliveryMode::None
    } else {
        CronDeliveryMode::Announce
    };
    Some(CronDelivery {
        mode,
        channel: cron_normalize_channel(channel.as_deref()),
        to: cron_normalize_to(to.as_deref()),
        best_effort: *best_effort_deliver,
    })
}

fn cron_delivery_patch_from_legacy_payload_patch(
    payload: &CronPayloadPatch,
) -> Option<CronDeliveryPatch> {
    let CronPayloadPatch::AgentTurn {
        deliver,
        channel,
        to,
        best_effort_deliver,
        ..
    } = payload
    else {
        return None;
    };

    let to_raw = to.as_deref().unwrap_or("").trim();
    let has_legacy_hints = deliver.is_some() || best_effort_deliver.is_some() || !to_raw.is_empty();
    if !has_legacy_hints {
        return None;
    }

    let mut patch = CronDeliveryPatch {
        mode: None,
        channel: None,
        to: None,
        best_effort: None,
    };
    let mut has_patch = false;

    if *deliver == Some(false) {
        patch.mode = Some(CronDeliveryMode::None);
        has_patch = true;
    } else if *deliver == Some(true) || !to_raw.is_empty() {
        patch.mode = Some(CronDeliveryMode::Announce);
        has_patch = true;
    }

    if let Some(ch) = channel.as_deref() {
        patch.channel = Some(ch.trim().to_ascii_lowercase());
        has_patch = true;
    }
    if let Some(to) = to.as_deref() {
        patch.to = Some(to.trim().to_string());
        has_patch = true;
    }
    if let Some(be) = best_effort_deliver {
        patch.best_effort = Some(*be);
        has_patch = true;
    }

    if has_patch {
        Some(patch)
    } else {
        None
    }
}

fn merge_cron_delivery(existing: Option<CronDelivery>, patch: CronDeliveryPatch) -> CronDelivery {
    let mut next = existing.unwrap_or(CronDelivery {
        mode: CronDeliveryMode::None,
        channel: None,
        to: None,
        best_effort: None,
    });
    if let Some(mode) = patch.mode {
        next.mode = mode;
    }
    if let Some(channel) = patch.channel {
        next.channel = cron_normalize_channel(Some(channel.as_str()));
    }
    if let Some(to) = patch.to {
        next.to = cron_normalize_to(Some(to.as_str()));
    }
    if let Some(best_effort) = patch.best_effort {
        next.best_effort = Some(best_effort);
    }
    next
}

fn resolve_cron_delivery_plan(job: &CronJob) -> CronDeliveryPlan {
    let payload = match &job.payload {
        CronPayload::AgentTurn {
            deliver,
            channel,
            to,
            best_effort_deliver,
            ..
        } => Some((deliver, channel, to, best_effort_deliver)),
        _ => None,
    };

    if let Some(delivery) = job.delivery.as_ref() {
        let requested = matches!(delivery.mode, CronDeliveryMode::Announce);
        let payload_channel = payload.and_then(|(_, ch, _, _)| ch.as_deref());
        let payload_to = payload.and_then(|(_, _, to, _)| to.as_deref());

        return CronDeliveryPlan {
            requested,
            channel: cron_normalize_channel(delivery.channel.as_deref().or(payload_channel)),
            to: cron_normalize_to(delivery.to.as_deref().or(payload_to)),
            best_effort: delivery.best_effort.unwrap_or(false),
        };
    }

    let Some((deliver, channel, to, best_effort_deliver)) = payload else {
        return CronDeliveryPlan {
            requested: false,
            channel: None,
            to: None,
            best_effort: false,
        };
    };

    let legacy_requested = match deliver {
        Some(true) => true,
        Some(false) => false,
        None => to.as_ref().map(|s| !s.trim().is_empty()).unwrap_or(false),
    };

    CronDeliveryPlan {
        requested: legacy_requested,
        channel: cron_normalize_channel(channel.as_deref()),
        to: cron_normalize_to(to.as_deref()),
        best_effort: best_effort_deliver.unwrap_or(false),
    }
}

fn compute_next_run_at_ms(schedule: &CronSchedule, now_ms: u64) -> Option<u64> {
    match schedule {
        CronSchedule::At { at } => cron_parse_absolute_time_ms(at).filter(|ms| *ms > now_ms),
        CronSchedule::Every {
            every_ms,
            anchor_ms,
        } => {
            let every = (*every_ms).max(1);
            let anchor = anchor_ms.unwrap_or(now_ms);
            if now_ms < anchor {
                return Some(anchor);
            }
            let elapsed = now_ms.saturating_sub(anchor);
            let steps = ((elapsed.saturating_add(every.saturating_sub(1))) / every).max(1);
            Some(anchor.saturating_add(steps.saturating_mul(every)))
        }
        CronSchedule::Cron { expr, tz } => {
            let expr = expr.trim();
            if expr.is_empty() {
                return None;
            }
            let parsed = drbot_cron::CronExpression::parse(expr).ok()?;

            let tz_parsed = tz
                .as_deref()
                .map(str::trim)
                .filter(|s| !s.is_empty())
                .and_then(|s| s.parse::<chrono_tz::Tz>().ok());

            let start_utc = chrono::DateTime::<chrono::Utc>::from_timestamp_millis(now_ms as i64)?
                + chrono::Duration::minutes(1);
            let mut candidate_utc = start_utc
                .with_second(0)
                .unwrap_or(start_utc)
                .with_nanosecond(0)
                .unwrap_or(start_utc);

            // Search for up to 4 years, minute-by-minute.
            let max_iterations = 365 * 4 * 24 * 60;
            for _ in 0..max_iterations {
                let matches = match tz_parsed {
                    Some(tz) => {
                        let dt = candidate_utc.with_timezone(&tz);
                        let minute = dt.minute();
                        let hour = dt.hour();
                        let dom = dt.day();
                        let month = dt.month();
                        let dow = dt.weekday().num_days_from_sunday();
                        parsed.minutes.contains(&minute)
                            && parsed.hours.contains(&hour)
                            && parsed.days_of_month.contains(&dom)
                            && parsed.months.contains(&month)
                            && parsed.days_of_week.contains(&dow)
                    }
                    None => {
                        let dt = candidate_utc.with_timezone(&chrono::Local);
                        let minute = dt.minute();
                        let hour = dt.hour();
                        let dom = dt.day();
                        let month = dt.month();
                        let dow = dt.weekday().num_days_from_sunday();
                        parsed.minutes.contains(&minute)
                            && parsed.hours.contains(&hour)
                            && parsed.days_of_month.contains(&dom)
                            && parsed.months.contains(&month)
                            && parsed.days_of_week.contains(&dow)
                    }
                };

                if matches {
                    return Some(candidate_utc.timestamp_millis().max(0) as u64);
                }
                candidate_utc = candidate_utc + chrono::Duration::minutes(1);
            }
            None
        }
    }
}

fn compute_job_next_run_at_ms(job: &CronJob, now_ms: u64) -> Option<u64> {
    if !job.enabled {
        return None;
    }

    match &job.schedule {
        CronSchedule::At { at } => {
            // One-shot jobs stay due until they successfully finish.
            if job.state.last_status == Some(CronRunStatus::Ok)
                && job.state.last_run_at_ms.is_some()
            {
                None
            } else {
                cron_parse_absolute_time_ms(at)
            }
        }
        CronSchedule::Every {
            every_ms,
            anchor_ms,
        } => {
            let every = (*every_ms).max(1);
            let anchor = anchor_ms.unwrap_or(job.created_at_ms);
            if now_ms < anchor {
                return Some(anchor);
            }
            let elapsed = now_ms.saturating_sub(anchor);
            let steps = ((elapsed.saturating_add(every.saturating_sub(1))) / every).max(1);
            Some(anchor.saturating_add(steps.saturating_mul(every)))
        }
        _ => compute_next_run_at_ms(&job.schedule, now_ms),
    }
}

fn next_wake_at_ms(jobs: &[CronJob]) -> Option<u64> {
    let mut next: Option<u64> = None;
    for job in jobs {
        if !job.enabled {
            continue;
        }
        let Some(ts) = job.state.next_run_at_ms else {
            continue;
        };
        next = Some(match next {
            Some(min) => min.min(ts),
            None => ts,
        });
    }
    next
}

fn merge_cron_payload(
    existing: &CronPayload,
    patch: CronPayloadPatch,
) -> Result<CronPayload, ErrorShape> {
    match (existing, patch) {
        (CronPayload::SystemEvent { text }, CronPayloadPatch::SystemEvent { text: patch_text }) => {
            Ok(CronPayload::SystemEvent {
                text: patch_text.unwrap_or_else(|| text.clone()),
            })
        }
        (
            CronPayload::AgentTurn {
                message,
                model,
                thinking,
                timeout_seconds,
                allow_unsafe_external_content,
                deliver,
                channel,
                to,
                best_effort_deliver,
            },
            CronPayloadPatch::AgentTurn {
                message: patch_message,
                model: patch_model,
                thinking: patch_thinking,
                timeout_seconds: patch_timeout_seconds,
                allow_unsafe_external_content: patch_allow_unsafe_external_content,
                deliver: patch_deliver,
                channel: patch_channel,
                to: patch_to,
                best_effort_deliver: patch_best_effort_deliver,
            },
        ) => Ok(CronPayload::AgentTurn {
            message: patch_message.unwrap_or_else(|| message.clone()),
            model: patch_model.or_else(|| model.clone()),
            thinking: patch_thinking.or_else(|| thinking.clone()),
            timeout_seconds: patch_timeout_seconds.or(*timeout_seconds),
            allow_unsafe_external_content: patch_allow_unsafe_external_content
                .or(*allow_unsafe_external_content),
            deliver: patch_deliver.or(*deliver),
            channel: patch_channel.or_else(|| channel.clone()),
            to: patch_to.or_else(|| to.clone()),
            best_effort_deliver: patch_best_effort_deliver.or(*best_effort_deliver),
        }),
        // Kind changed; require required field to be present and non-empty.
        (_, CronPayloadPatch::SystemEvent { text }) => {
            let Some(text) = text else {
                return Err(ErrorShape::new(
                    error_codes::INVALID_REQUEST,
                    r#"cron.update payload.kind="systemEvent" requires text"#,
                ));
            };
            if text.is_empty() {
                return Err(ErrorShape::new(
                    error_codes::INVALID_REQUEST,
                    r#"cron.update payload.kind="systemEvent" requires non-empty text"#,
                ));
            }
            Ok(CronPayload::SystemEvent { text })
        }
        (
            _,
            CronPayloadPatch::AgentTurn {
                message,
                model,
                thinking,
                timeout_seconds,
                allow_unsafe_external_content,
                deliver,
                channel,
                to,
                best_effort_deliver,
            },
        ) => {
            let Some(message) = message else {
                return Err(ErrorShape::new(
                    error_codes::INVALID_REQUEST,
                    r#"cron.update payload.kind="agentTurn" requires message"#,
                ));
            };
            if message.is_empty() {
                return Err(ErrorShape::new(
                    error_codes::INVALID_REQUEST,
                    r#"cron.update payload.kind="agentTurn" requires non-empty message"#,
                ));
            }
            Ok(CronPayload::AgentTurn {
                message,
                model,
                thinking,
                timeout_seconds,
                allow_unsafe_external_content,
                deliver,
                channel,
                to,
                best_effort_deliver,
            })
        }
    }
}

#[derive(Debug)]
struct OpenclawCronState {
    loaded: bool,
    store: CronStoreFile,
}

#[derive(Debug)]
struct OpenclawCronService {
    store_path: PathBuf,
    enabled: bool,
    started: std::sync::atomic::AtomicBool,
    notify: Notify,
    state: Mutex<OpenclawCronState>,
}

static OPENCLAW_CRON_SERVICES: OnceLock<Mutex<HashMap<PathBuf, Arc<OpenclawCronService>>>> =
    OnceLock::new();

fn openclaw_cron_services() -> &'static Mutex<HashMap<PathBuf, Arc<OpenclawCronService>>> {
    OPENCLAW_CRON_SERVICES.get_or_init(|| Mutex::new(HashMap::new()))
}

async fn cron_service_for_state(state: &GatewayState) -> Arc<OpenclawCronService> {
    let store_path = resolve_openclaw_cron_store_path(state);
    let mut services = openclaw_cron_services().lock().await;
    if let Some(svc) = services.get(&store_path) {
        // Ensure background loop started (idempotent).
        svc.start_background(state.clone());
        return svc.clone();
    }

    let enabled = std::env::var("OPENCLAW_SKIP_CRON").ok().as_deref() != Some("1")
        && std::env::var("DRBOT_SKIP_CRON").ok().as_deref() != Some("1");
    let svc = Arc::new(OpenclawCronService {
        store_path: store_path.clone(),
        enabled,
        started: std::sync::atomic::AtomicBool::new(false),
        notify: Notify::new(),
        state: Mutex::new(OpenclawCronState {
            loaded: false,
            store: CronStoreFile {
                version: 1,
                jobs: Vec::new(),
            },
        }),
    });
    svc.start_background(state.clone());
    services.insert(store_path, svc.clone());
    svc
}

impl OpenclawCronService {
    fn start_background(self: &Arc<Self>, state: GatewayState) {
        if !self.enabled {
            return;
        }
        if self
            .started
            .compare_exchange(false, true, Ordering::Relaxed, Ordering::Relaxed)
            .is_err()
        {
            return;
        }

        let svc = self.clone();
        tokio::spawn(async move {
            svc.run_loop(state).await;
        });
    }

    async fn ensure_loaded_locked(&self, st: &mut OpenclawCronState) {
        if st.loaded {
            return;
        }
        st.store = load_cron_store(&self.store_path);
        st.loaded = true;

        let now = now_ms();
        // Best-effort migration for OpenClaw parity:
        // - Ensure "every" schedules have a stable anchorMs (avoids drift across restarts).
        // - Ensure isolated agentTurn jobs have a delivery object (OpenClaw defaults to announce).
        for job in &mut st.store.jobs {
            if let CronSchedule::Every { anchor_ms, .. } = &mut job.schedule {
                if anchor_ms.is_none() {
                    *anchor_ms = Some(job.created_at_ms);
                }
            }

            let is_isolated_agent_turn = matches!(job.session_target, CronSessionTarget::Isolated)
                && matches!(&job.payload, CronPayload::AgentTurn { .. });
            if is_isolated_agent_turn {
                if job.delivery.is_none() {
                    job.delivery = if cron_has_legacy_delivery_hints(&job.payload) {
                        cron_delivery_from_legacy_payload(&job.payload)
                    } else {
                        Some(CronDelivery {
                            mode: CronDeliveryMode::Announce,
                            channel: None,
                            to: None,
                            best_effort: None,
                        })
                    };
                }
                if let Some(delivery) = job.delivery.as_mut() {
                    delivery.channel = cron_normalize_channel(delivery.channel.as_deref());
                    delivery.to = cron_normalize_to(delivery.to.as_deref());
                }
            } else {
                job.delivery = None;
            }
        }
        recompute_next_runs(&mut st.store.jobs, now);
        let _ = write_json_atomic(&self.store_path, &st.store);
    }

    async fn persist_locked(&self, st: &OpenclawCronState) -> Result<(), ErrorShape> {
        write_json_atomic(&self.store_path, &st.store)
    }

    async fn run_loop(self: Arc<Self>, state: GatewayState) {
        loop {
            let next_at = {
                let mut st = self.state.lock().await;
                self.ensure_loaded_locked(&mut st).await;
                next_wake_at_ms(&st.store.jobs)
            };

            let Some(next_at) = next_at else {
                self.notify.notified().await;
                continue;
            };

            let delay_ms = next_at.saturating_sub(now_ms());
            tokio::select! {
                _ = tokio::time::sleep(Duration::from_millis(delay_ms)) => {
                    let _ = self.run_due_jobs(&state).await;
                }
                _ = self.notify.notified() => {
                    continue;
                }
            }
        }
    }

    async fn status(&self) -> serde_json::Value {
        let mut st = self.state.lock().await;
        self.ensure_loaded_locked(&mut st).await;
        let next = if self.enabled {
            next_wake_at_ms(&st.store.jobs)
        } else {
            None
        };
        json!({
            "enabled": self.enabled,
            "storePath": self.store_path.to_string_lossy(),
            "jobs": st.store.jobs.len(),
            "nextWakeAtMs": next,
        })
    }

    async fn list(&self, include_disabled: bool) -> Vec<CronJob> {
        let mut st = self.state.lock().await;
        self.ensure_loaded_locked(&mut st).await;
        let now = now_ms();
        recompute_next_runs(&mut st.store.jobs, now);
        let mut jobs = st
            .store
            .jobs
            .iter()
            .cloned()
            .filter(|j| include_disabled || j.enabled)
            .collect::<Vec<_>>();
        jobs.sort_by_key(|j| j.state.next_run_at_ms.unwrap_or(0));
        jobs
    }

    async fn add(&self, state: &GatewayState, input: CronAddParams) -> Result<CronJob, ErrorShape> {
        if !self.enabled {
            warn!("cron: disabled; add called");
        }

        let now = now_ms();
        let name = input.name.trim();
        if name.is_empty() {
            return Err(ErrorShape::new(
                error_codes::INVALID_REQUEST,
                "cron job name is required",
            ));
        }
        let agent_id = input.agent_id.unwrap_or(None).and_then(|s| {
            let trimmed = s.trim();
            if trimmed.is_empty() {
                None
            } else {
                Some(trimmed.to_string())
            }
        });
        let description = input.description.and_then(|s| {
            let trimmed = s.trim().to_string();
            if trimmed.is_empty() {
                None
            } else {
                Some(trimmed)
            }
        });
        let enabled = input.enabled.unwrap_or(true);

        let mut schedule = input.schedule;
        if let CronSchedule::Every { anchor_ms, .. } = &mut schedule {
            if anchor_ms.is_none() {
                *anchor_ms = Some(now);
            }
        }

        let delete_after_run = match input.delete_after_run {
            Some(v) => Some(v),
            None => {
                if matches!(schedule, CronSchedule::At { .. }) {
                    Some(true)
                } else {
                    None
                }
            }
        };

        let payload = input.payload;
        let session_target = input.session_target;
        let mut delivery = input.delivery;
        if matches!(session_target, CronSessionTarget::Isolated)
            && matches!(&payload, CronPayload::AgentTurn { .. })
        {
            if delivery.is_none() {
                delivery = if cron_has_legacy_delivery_hints(&payload) {
                    cron_delivery_from_legacy_payload(&payload)
                } else {
                    Some(CronDelivery {
                        mode: CronDeliveryMode::Announce,
                        channel: None,
                        to: None,
                        best_effort: None,
                    })
                };
            }
            if let Some(delivery) = delivery.as_mut() {
                delivery.channel = cron_normalize_channel(delivery.channel.as_deref());
                delivery.to = cron_normalize_to(delivery.to.as_deref());
            }
        } else if delivery.is_some() {
            return Err(ErrorShape::new(
                error_codes::INVALID_REQUEST,
                r#"cron delivery config is only supported for sessionTarget="isolated""#,
            ));
        }

        let job = CronJob {
            id: Uuid::new_v4().to_string(),
            agent_id,
            name: name.to_string(),
            description,
            enabled,
            delete_after_run,
            created_at_ms: now,
            updated_at_ms: now,
            schedule,
            session_target,
            wake_mode: input.wake_mode,
            payload,
            delivery,
            isolation: input.isolation,
            state: CronJobState::default(),
        };

        assert_supported_job_spec(&job)?;
        assert_delivery_support(&job)?;

        let mut st = self.state.lock().await;
        self.ensure_loaded_locked(&mut st).await;
        let mut job = job;
        job.state.next_run_at_ms = compute_job_next_run_at_ms(&job, now);
        st.store.jobs.push(job.clone());
        self.persist_locked(&st).await?;
        self.notify.notify_one();

        broadcast_openclaw_event(
            state,
            "cron",
            json!({ "jobId": job.id, "action": "added", "nextRunAtMs": job.state.next_run_at_ms }),
            None,
        )
        .await;

        Ok(job)
    }

    async fn update(
        &self,
        state: &GatewayState,
        job_id: &str,
        patch: CronJobPatch,
    ) -> Result<CronJob, ErrorShape> {
        if job_id.trim().is_empty() {
            return Err(ErrorShape::new(error_codes::INVALID_REQUEST, "missing id"));
        }
        let now = now_ms();

        let mut st = self.state.lock().await;
        self.ensure_loaded_locked(&mut st).await;
        let job = st
            .store
            .jobs
            .iter_mut()
            .find(|j| j.id == job_id)
            .ok_or_else(|| {
                ErrorShape::new(
                    error_codes::INVALID_REQUEST,
                    format!("unknown cron job id: {}", job_id),
                )
            })?;

        let payload_patch_for_delivery = patch.payload.clone();
        let has_delivery_patch = patch.delivery.is_some();
        let schedule_changed = patch.schedule.is_some();
        let enabled_changed = patch.enabled.is_some();

        if let Some(name) = patch.name.as_deref() {
            let trimmed = name.trim();
            if trimmed.is_empty() {
                return Err(ErrorShape::new(
                    error_codes::INVALID_REQUEST,
                    "cron job name is required",
                ));
            }
            job.name = trimmed.to_string();
        }
        if let Some(desc) = patch.description {
            let trimmed = desc.trim().to_string();
            job.description = if trimmed.is_empty() {
                None
            } else {
                Some(trimmed)
            };
        }
        if let Some(enabled) = patch.enabled {
            job.enabled = enabled;
        }
        if let Some(delete_after_run) = patch.delete_after_run {
            job.delete_after_run = Some(delete_after_run);
        }
        if let Some(mut schedule) = patch.schedule {
            if let CronSchedule::Every { anchor_ms, .. } = &mut schedule {
                if anchor_ms.is_none() {
                    *anchor_ms = Some(now);
                }
            }
            job.schedule = schedule;
        }
        if let CronSchedule::Every { anchor_ms, .. } = &mut job.schedule {
            if anchor_ms.is_none() {
                *anchor_ms = Some(if schedule_changed {
                    now
                } else {
                    job.created_at_ms
                });
            }
        }
        if let Some(session_target) = patch.session_target {
            job.session_target = session_target;
        }
        if let Some(wake_mode) = patch.wake_mode {
            job.wake_mode = wake_mode;
        }
        if let Some(payload_patch) = patch.payload {
            job.payload = merge_cron_payload(&job.payload, payload_patch)?;
        }
        if !has_delivery_patch {
            if let Some(payload_patch) = payload_patch_for_delivery.as_ref() {
                if let Some(legacy_patch) =
                    cron_delivery_patch_from_legacy_payload_patch(payload_patch)
                {
                    if matches!(job.session_target, CronSessionTarget::Isolated)
                        && matches!(&job.payload, CronPayload::AgentTurn { .. })
                    {
                        job.delivery =
                            Some(merge_cron_delivery(job.delivery.clone(), legacy_patch));
                    }
                }
            }
        }
        if let Some(delivery_patch) = patch.delivery {
            job.delivery = Some(merge_cron_delivery(job.delivery.clone(), delivery_patch));
        }
        if let Some(isolation) = patch.isolation {
            job.isolation = Some(isolation);
        }
        if let Some(state_patch) = patch.state {
            if let Some(v) = state_patch.next_run_at_ms {
                job.state.next_run_at_ms = Some(v);
            }
            if let Some(v) = state_patch.running_at_ms {
                job.state.running_at_ms = Some(v);
            }
            if let Some(v) = state_patch.last_run_at_ms {
                job.state.last_run_at_ms = Some(v);
            }
            if let Some(v) = state_patch.last_status {
                job.state.last_status = Some(v);
            }
            if let Some(v) = state_patch.last_error {
                job.state.last_error = Some(v);
            }
            if let Some(v) = state_patch.last_duration_ms {
                job.state.last_duration_ms = Some(v);
            }
            if let Some(v) = state_patch.consecutive_errors {
                job.state.consecutive_errors = Some(v);
            }
        }
        if let Some(agent_field) = patch.agent_id {
            job.agent_id = agent_field.and_then(|s| {
                let trimmed = s.trim();
                if trimmed.is_empty() {
                    None
                } else {
                    Some(trimmed.to_string())
                }
            });
        }

        // Normalize delivery config (OpenClaw parity).
        let is_isolated_agent_turn = matches!(job.session_target, CronSessionTarget::Isolated)
            && matches!(&job.payload, CronPayload::AgentTurn { .. });
        if is_isolated_agent_turn {
            if job.delivery.is_none() {
                job.delivery = if cron_has_legacy_delivery_hints(&job.payload) {
                    cron_delivery_from_legacy_payload(&job.payload)
                } else {
                    Some(CronDelivery {
                        mode: CronDeliveryMode::Announce,
                        channel: None,
                        to: None,
                        best_effort: None,
                    })
                };
            }
            if let Some(delivery) = job.delivery.as_mut() {
                delivery.channel = cron_normalize_channel(delivery.channel.as_deref());
                delivery.to = cron_normalize_to(delivery.to.as_deref());
            }
        } else {
            job.delivery = None;
        }

        assert_supported_job_spec(job)?;
        assert_delivery_support(job)?;
        job.updated_at_ms = now;

        if schedule_changed || enabled_changed {
            if job.enabled {
                job.state.next_run_at_ms = compute_job_next_run_at_ms(job, now);
            } else {
                job.state.next_run_at_ms = None;
                job.state.running_at_ms = None;
            }
        }

        let updated = job.clone();
        self.persist_locked(&st).await?;
        self.notify.notify_one();

        broadcast_openclaw_event(
            state,
            "cron",
            json!({ "jobId": job_id, "action": "updated", "nextRunAtMs": updated.state.next_run_at_ms }),
            None,
        )
        .await;

        Ok(updated)
    }

    async fn remove(
        &self,
        state: &GatewayState,
        job_id: &str,
    ) -> Result<serde_json::Value, ErrorShape> {
        if job_id.trim().is_empty() {
            return Err(ErrorShape::new(error_codes::INVALID_REQUEST, "missing id"));
        }
        let mut st = self.state.lock().await;
        self.ensure_loaded_locked(&mut st).await;
        let before = st.store.jobs.len();
        st.store.jobs.retain(|j| j.id != job_id);
        let removed = st.store.jobs.len() != before;
        self.persist_locked(&st).await?;
        self.notify.notify_one();
        if removed {
            broadcast_openclaw_event(
                state,
                "cron",
                json!({ "jobId": job_id, "action": "removed" }),
                None,
            )
            .await;
        }
        Ok(json!({ "ok": true, "removed": removed }))
    }

    async fn run(
        &self,
        state: &GatewayState,
        job_id: &str,
        mode: Option<&str>,
    ) -> Result<serde_json::Value, ErrorShape> {
        if job_id.trim().is_empty() {
            return Err(ErrorShape::new(error_codes::INVALID_REQUEST, "missing id"));
        }
        let forced = mode == Some("force");
        let now = now_ms();

        let mut st = self.state.lock().await;
        self.ensure_loaded_locked(&mut st).await;
        let idx = st
            .store
            .jobs
            .iter()
            .position(|j| j.id == job_id)
            .ok_or_else(|| {
                ErrorShape::new(
                    error_codes::INVALID_REQUEST,
                    format!("unknown cron job id: {}", job_id),
                )
            })?;

        let due = {
            let job = &st.store.jobs[idx];
            if forced {
                true
            } else {
                job.enabled
                    && job.state.next_run_at_ms.is_some()
                    && now >= job.state.next_run_at_ms.unwrap_or(u64::MAX)
            }
        };
        if !due {
            return Ok(json!({ "ok": true, "ran": false, "reason": "not-due" }));
        }

        // Execute inside lock to keep store consistent (matches OpenClaw semantics).
        let job_id = st.store.jobs[idx].id.clone();
        execute_cron_job(state, &self.store_path, &mut st.store, &job_id, forced).await;
        // Persist store changes.
        self.persist_locked(&st).await?;
        self.notify.notify_one();
        Ok(json!({ "ok": true, "ran": true }))
    }

    async fn run_due_jobs(&self, state: &GatewayState) -> Result<(), ErrorShape> {
        let now = now_ms();
        let mut st = self.state.lock().await;
        self.ensure_loaded_locked(&mut st).await;
        recompute_next_runs(&mut st.store.jobs, now);

        // Collect due job IDs first (so we can mutate safely during execution).
        let due_ids: Vec<String> = st
            .store
            .jobs
            .iter()
            .filter(|j| {
                j.enabled
                    && j.state.running_at_ms.is_none()
                    && j.state.next_run_at_ms.is_some()
                    && now >= j.state.next_run_at_ms.unwrap_or(u64::MAX)
            })
            .map(|j| j.id.clone())
            .collect();

        for id in due_ids {
            execute_cron_job(state, &self.store_path, &mut st.store, &id, false).await;
        }

        self.persist_locked(&st).await?;
        Ok(())
    }
}

pub(crate) async fn openclaw_cron_status_for_tool(state: &GatewayState) -> serde_json::Value {
    let svc = cron_service_for_state(state).await;
    svc.status().await
}

pub(crate) async fn openclaw_cron_list_for_tool(
    state: &GatewayState,
    include_disabled: bool,
) -> serde_json::Value {
    let svc = cron_service_for_state(state).await;
    let jobs = svc.list(include_disabled).await;
    json!({ "jobs": jobs })
}

pub(crate) async fn openclaw_cron_add_for_tool(
    state: &GatewayState,
    job: serde_json::Value,
) -> Result<serde_json::Value, ErrorShape> {
    let params: CronAddParams = serde_json::from_value(job).map_err(|e| {
        ErrorShape::new(
            error_codes::INVALID_REQUEST,
            format!("invalid cron.add params: {}", e),
        )
    })?;
    let svc = cron_service_for_state(state).await;
    let job = svc.add(state, params).await?;
    Ok(json!(job))
}

